B.bg4=s(["Konekte","Se connecter","Sign in"],t.s)
B.bkN=s(["Dekonekte","Se d\xe9connecter","Sign out"],t.s)
B.bi7=s(["Im\xe8l","Email","Email"],t.s)
B.bF4=s(["Pri renouv\xe8lman","Tarif de renouvellement","Renewal price"],t.s)
B.bDR=s(["Pri enskripsyon, premye pery\xf2d ladan l","Inscription, premi\xe8re p\xe9riode incluse","Registration, first period included"],t.s)
B.boC=s(["Pri total premye enskripsyon an. Kite vid pou itilize pri renouv\xe8lman an.","Prix total de la premi\xe8re inscription. Vide : m\xeame prix que le renouvellement.","Total first registration price. Leave blank to use the renewal price."],t.s)
B.bCc=s(["Im\xe8l obligatwa pou resevwa konfimasyon enskripsyon ak renouv\xe8lman yo.","Email requis pour recevoir les confirmations d\u2019inscription et de renouvellement.","Email required for registration and renewal confirmations."],t.s)
B.bAZ=s(["Manm ki te deja la","Membre d\xe9j\xe0 inscrit \xe0 la salle","Existing gym member"],t.s)
B.bhh=s(["Reprann yon manm nan ansyen kaye a, san fr\xe8 enskripsyon.","Reprise du registre existant, sans frais d\u2019inscription.","Import from the existing register, without registration fees."],t.s)
B.aZy=s(["Chwazi pery\xf2d li te deja peye a","Choisir la p\xe9riode d\xe9j\xe0 r\xe9gl\xe9e","Choose the previously paid period"],t.s)
B.bci=s(["Pery\xf2d sa a deja peye. Pa gen nouvo lajan k ap antre nan k\xe8s la.","P\xe9riode d\xe9j\xe0 r\xe9gl\xe9e : aucun nouvel encaissement dans la caisse.","Already paid: no new cash receipt will be recorded."],t.s)
B.b4Y=s(["Pery\xf2d reprann nan kaye a","P\xe9riode reprise du registre","Period imported from register"],t.s)
B.bfV=s(["Swivi im\xe8l yo","Suivi des emails","Email status"],t.s)
B.bCw=s(["Limit pataje / 24 \xe8dtan","Limite partag\xe9e / 24 heures","Shared limit / 24 hours"],t.s)
B.bis=s(["An atant","En attente","Queued"],t.s)
B.bgC=s(["Ap voye","En cours","Sending"],t.s)
B.bAo=s(["Voye","Envoy\xe9s","Sent"],t.s)
B.bx4=s(["Pou korije","\xc0 corriger","Needs correction"],t.s)
B.bp2=s(["Pou verifye","\xc0 v\xe9rifier","Needs review"],t.s)
B.aQE=s(["Poz jiska","Pause jusqu\u2019au","Paused until"],t.s)
B.byU=s(["L\xe8 limit jounen an rive, im\xe8l yo rete an atant epi yo pati otomatikman apre. Kontakte sip\xf2 SecurGYM si gen im\xe8l pou korije oswa verifye.","Limite du jour atteinte : les emails restent en attente et partent automatiquement ensuite. Contactez le support SecurGYM pour les emails \xe0 corriger ou v\xe9rifier.","When the daily limit is reached, emails stay queued and go out automatically later. Contact SecurGYM support about emails needing correction or review."],t.s)
B.aNl=s(["Swivi im\xe8l pa disponib. Verifye ent\xe8n\xe8t ak konfigirasyon s\xe8v\xe8 a.","Suivi indisponible. V\xe9rifiez le r\xe9seau et la configuration serveur.","Email status unavailable. Check the network and server configuration."],t.s)
B.bfz=s(["Im\xe8l konfimasyon an ap voye otomatikman apre senkronizasyon.","L\u2019email de confirmation partira automatiquement apr\xe8s synchronisation.","The confirmation email will be sent automatically after synchronization."],t.s)
B.bou=s(["Modpas","Mot de passe","Password"],t.s)
B.bpX=s(["Montre modpas la","Afficher le mot de passe","Show password"],t.s)
B.bzx=s(["Kache modpas la","Masquer le mot de passe","Hide password"],t.s)
B.brG=s(["S\xe8vi ak kont responsab sal la ba ou a.","Utilisez le compte fourni par votre responsable.","Use the account provided by your gym administrator."],t.s)
B.b0I=s(["Chan sa a obligatwa.","Ce champ est obligatoire.","This field is required."],t.s)
B.bD9=s(["Antre yon adr\xe8s im\xe8l ki valab.","Saisissez une adresse email valide.","Enter a valid email address."],t.s)
B.bB0=s(["Koneksyon an echwe. Verifye im\xe8l ak modpas ou.","Connexion impossible. V\xe9rifiez votre email et votre mot de passe.","Sign-in failed. Check your email and password."],t.s)
B.bor=s(["S\xe8v\xe8 a pa aksesib. Verifye koneksyon ou.","Serveur inaccessible. V\xe9rifiez votre connexion.","Server unreachable. Check your connection."],t.s)
B.bl8=s(["Ak\xe8y","Accueil","Home"],t.s)
B.bed=s(["Param\xe8t","Param\xe8tres","Settings"],t.s)
B.bvW=s(["Senkronizasyon","Synchronisation","Synchronization"],t.s)
B.boD=s(["Senkronize","Synchroniser","Sync now"],t.s)
B.bcp=s(["Verifye tout done yo","R\xe9concilier toutes les donn\xe9es","Reconcile all data"],t.s)
B.bmW=s(["Anliy","En ligne","Online"],t.s)
B.aMb=s(["San ent\xe8n\xe8t","Hors ligne","Offline"],t.s)
B.b1l=s(["Senkronizasyon ap f\xe8t","Synchronisation en cours","Synchronizing"],t.s)
B.bxW=s(["An atant","En attente","Pending"],t.s)
B.b0K=s(["Ech\xe8k","\xc9checs","Failed"],t.s)
B.biL=s(["Konfli","Conflits","Conflicts"],t.s)
B.aKK=s(["S\xe8v\xe8 a te kons\xe8ve yon l\xf2t v\xe8syon. Done lokal orijinal yo rete kons\xe8ve pou revizyon.","Le serveur a conserv\xe9 une autre version. Les donn\xe9es locales originales sont conserv\xe9es pour r\xe9vision.","The server kept another version. Original local data is retained for review."],t.s)
B.bih=s(["Mwen verifye sa","Marquer comme v\xe9rifi\xe9","Mark reviewed"],t.s)
B.byN=s(["Pa gen operasyon an atant.","Aucune op\xe9ration en attente.","No pending operations."],t.s)
B.beY=s(["Pa gen konfli pou verifye.","Aucun conflit \xe0 v\xe9rifier.","No conflicts to review."],t.s)
